// Import only what you need from Firebase v9 modular SDK
// i// Import the functions you need
import { initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";

// Your Firebase config
const firebaseConfig = {
  apiKey: "AIzaSyBzYWIjOs4t3UFW3qqlKKOzs_sjiWcrL_w",
  authDomain: "fir-7242f.firebaseapp.com",
  projectId: "fir-7242f",
  storageBucket: "fir-7242f.firebasestorage.app",
  messagingSenderId: "651996830719",
  appId: "1:651996830719:web:b2663d1a77059c5d9ba5ca",
  measurementId: "G-NX9H4MWH8L"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Export modular instances
export const auth = getAuth(app);
export const db = getFirestore(app);
export const Firebase = { auth, db };
